/*
 * A191106  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x-2 and 3x are in a.
 * https://oeis.org/A191106
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   not stated
 * Range:     u8 n <= 20, u16 n <= 1023, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* OEIS A191106: a(1)=1; if x∈a then 3x-2 and 3x are in a.
   Sequence generated by BFS using a min‑heap to produce the sorted
   increasing sequence. */

#include <stdlib.h>
#include <stdbool.h>
#include <stdint.h>

/* static storage for the sequence and the priority queue */
static seq_t *seq      = NULL;
static size_t seq_cap  = 0;   /* capacity of seq array */
static size_t seq_len  = 0;   /* number of elements stored */

static seq_t *heap     = NULL;
static size_t heap_cap = 0;   /* capacity of heap array */
static size_t heap_len = 0;   /* number of elements in heap */

/* ------------------------------------------------------------------ */
/* heap utilities                                                      */
/* ------------------------------------------------------------------ */
static void heap_push(seq_t v)
{
    if (heap_len == heap_cap) {
        heap_cap = (heap_cap == 0) ? 16 : heap_cap * 2;
        heap = (seq_t *)realloc(heap, heap_cap * sizeof(seq_t));
    }
    size_t i = heap_len++;
    heap[i] = v;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap[p] <= heap[i]) break;
        seq_t t = heap[p];
        heap[p] = heap[i];
        heap[i] = t;
        i = p;
    }
}

static seq_t heap_pop(void)
{
    seq_t v = heap[0];
    --heap_len;
    if (heap_len > 0) {
        heap[0] = heap[heap_len];
        size_t i = 0;
        while (1) {
            size_t l = (i << 1) + 1;
            size_t r = l + 1;
            size_t m = i;
            if (l < heap_len && heap[l] < heap[m]) m = l;
            if (r < heap_len && heap[r] < heap[m]) m = r;
            if (m == i) break;
            seq_t t = heap[i];
            heap[i] = heap[m];
            heap[m] = t;
            i = m;
        }
    }
    return v;
}

/* ------------------------------------------------------------------ */
/* sequence generation                                               */
/* ------------------------------------------------------------------ */
static void build_up_to(idx_t n)
{
    if (seq_len >= (size_t)n)
        return;                     /* already generated */

    /* initialise first element if needed */
    if (seq_len == 0) {
        seq_cap = 16;
        seq = (seq_t *)malloc(seq_cap * sizeof(seq_t));
        seq[0] = (seq_t)1;
        seq_len = 1;

        heap_cap = 16;
        heap = (seq_t *)malloc(heap_cap * sizeof(seq_t));
        heap_len = 0;
        /* children of 1: 3*1-2 = 1 (duplicate) and 3*1 = 3 */
        heap_push((seq_t)3);        /* only the unique child */
    }

    while (seq_len < (size_t)n) {
        seq_t val = heap_pop();     /* smallest not yet processed */
        /* store it */
        if (seq_len == seq_cap) {
            seq_cap *= 2;
            seq = (seq_t *)realloc(seq, seq_cap * sizeof(seq_t));
        }
        seq[seq_len++] = val;

        /* generate children */
        if (val != (seq_t)1)        /* 3*1-2 would be 1 again */
            heap_push(3 * val - 2);
        heap_push(3 * val);
    }
}

/* ------------------------------------------------------------------ */
/* public function                                                   */
/* ------------------------------------------------------------------ */
seq_t a(idx_t n)
{
    if (n == 0)         /* undefined for n < 1; behave gracefully */
        return (seq_t)0;
    build_up_to(n);
    return seq[(size_t)n - 1];
}
